"""Literal common-AE quantifier versus the standard per-observable definition."""
from ch05_data import add,copied,proposition,D,NS
add('UniformMicroErgodic','5.4.1',197,[58],r'''Definition 5.1 A Hamiltonian system is said to be ergodic on an energy surface $\Sigma_E$ (microcanonically ergodic) if, for almost all trajectories $\tau$ emanating from initial conditions on $\Sigma_E$, and for any observable $g$, the following holds $\bar g=\operatorname{Av}_{H=E}(g)$, where $\bar g$ is defined in (5.9). By “almost all” we mean that there could be a low-dimensional subset for which the trajectory averages fail to equal the space averages.''',f'''def uniformMicroErgodic {{n : ℕ}} (H : {NS}E n → ℝ) (c : ℝ) (Φ : ℝ → {NS}E n → {NS}E n) : Prop :=
  ∀ᵐ z ∂{NS}microMeasure H c,∀ g : {NS}E n → ℝ,
    ContDiff ℝ ⊤ g → Integrable g ({NS}microMeasure H c) →
      {NS}hasTimeAverage (fun t => Φ t z) g ({NS}microAverage H c g)''',kind='definition',label='Definition 5.1',verdict='NEEDS_HUMAN',explanation='字面量词记录共满测集上的∀光滑可观测量；不静默交换∀g与AEz。原“低维例外”的表述不等价于一般零测集合；标准逐可观测量AE版本另条。',extra=['[EXTRA]沿用前文光滑可观测量且明确µ可积，避免给不存在空间平均的函数套等式；AE采用真实µ_E零测资格。'])
add('MicroErgodicStandard','5.4.1',197,[58],r'''for almost all trajectories $\tau$ emanating from initial conditions on $\Sigma_E$, and for any observable $g$, $\bar g=\operatorname{Av}_{H=E}(g)$.''',copied(D,'microErgodic'),kind='definition',extra=['[EXTRA]标准每个L¹可观测量各自AE初值版本，和原字面共满测集版本分开；不声称两者已等价。'])
add('FlowInvariant','5.4.1','197–198',[59],r'''An invariant set $A$ of the flow is one such that $\mathcal F_t(A)=A$, for all $t\ne0$.''',copied(D,'flowInvariant'),kind='definition',extra=['[EXTRA]原t≠0；真实流的零时刻恒等自动补上t=0，因而用实际全实时间集合像不变性。仅给定的真实流可解释为动力系统不变性。'])
add('SetErgodic','5.4.1','197–198',[59],r'''Alternatively, we may say that a dynamical system as ergodic if the probability measure of any invariant set $A$ of the flow is either 0 or 1.''',copied(D,'setErgodic'),kind='definition',extra=['[EXTRA]明示集合可测和实际概率测度背景；原“as ergodic”字面保留，不在逐字JSON中默改为“is”。'])
add('InvariantIndicator','5.4.1',198,[60],r'''Then for any trajectory starting in $A$, we have that the average of $\phi$ along $\tau$ vanishes, i.e. $\bar\phi=\lim_{T\to\infty}T^{-1}\int_0^T\phi(z(t))dt=0$, since $A$ is an invariant set.''',copied('MolecularDynamics/Chapter05/ReviewProofs.lean','invariantIndicator_proved','invariantIndicator'),extra=['[EXTRA]原φ是可达空间内A的补集示性函数，实际Measure支撑空间限定时可用ambient Aᶜ示性函数；本条保留沿轨道逐点为零，完整无限时间平均另条。'],prior=['MolecularDynamics.Chapter05Review.invariantIndicator_proved'])
add('InvariantIndicatorAverage','5.4.1',198,[60],r'''$\bar\phi=\lim_{T\to\infty}T^{-1}\int_0^T\phi(z(t))dt=0$, since $A$ is an invariant set.''',f'''theorem invariantIndicatorAverage {{X : Type*}} (Φ : ℝ → X → X) (A : Set X)
    (hA : {NS}flowInvariant Φ A) (z : X) (hz : z ∈ A) :
  {NS}hasTimeAverage (fun t => Φ t z) (Aᶜ.indicator (fun _ => (1 : ℝ))) 0 := by
  sorry''',context=['保留真实无限时间平均，不仅逐点补集indicator为0；书中该indicator不一定光滑，需要L¹观测量资格，未用它默证共AE光滑定义的等价性。'])
add('ErgodicTimeEquivalence','5.4.1',198,[61],r'''If we assume the system is ergodic, we must have $\operatorname{Pr}(\Sigma_E\setminus A)=0$, thus $\operatorname{Pr}(A)=1$. Since, according to the definition, equality of time and space averages is allowed to fail only on a set of probability measure zero, we have that either $\operatorname{Pr}(A)=0$ or $\operatorname{Pr}(A)=1$.''',proposition('ergodicTimeAverage_statement'),extra=['[EXTRA]完整全实时间可测流、概率保持、群律及L¹资格；对应标准每观测量AE版本，未将原共满测集量词交换当无条件事实。'],missing='Mathlib存在离散Birkhoff/Ergodic基础，但缺本章连续时间积分平均与集合遍历性等价的接口；不建设大型遍历理论。')
add('NonergodicSet','5.4.1',198,[62],r'''If a system is not ergodic, then there will be an invariant set $A$ whose probability measure is strictly between zero and one. The trajectories emanating from this set are unable to explore the entire energy surface and the corresponding trajectory averages will, at least for some observables, be different than the spatial average of that observable.''',proposition('nonergodicSet_statement'),context=['实际集合遍历性的逻辑等价；严格中间概率完整保留，不把不变集合的存在假设作结论。'])
